select 'ledger_total' k, (select count(*)::text from supabase_migrations.schema_migrations) v
union all select 'ledger_max', (select max(version) from supabase_migrations.schema_migrations)
union all select 'ledger_149_rows', (select count(*)::text from supabase_migrations.schema_migrations where version='20260924120000')
union all select 'ledger_148', coalesce((select version||' | '||name||' | by='||coalesce(created_by,'<null>')||' | stmts='||coalesce(array_length(statements,1),0)::text||' | stmt_md5='||md5(statements[1]) from supabase_migrations.schema_migrations where version='20260924000000'),'<no row>')
union all select 'a3', (select 'defn='||md5(pg_get_functiondef(p.oid))||' prosrc='||md5(p.prosrc)||' | args='||pg_get_function_identity_arguments(p.oid)||' | result='||pg_get_function_result(p.oid)||' | secdef='||p.prosecdef::text||' | cfg='||coalesce(array_to_string(p.proconfig,';'),'<none>')||' | acl='||coalesce(p.proacl::text,'<default>')||' owner='||p.proowner::regrole::text from pg_proc p where p.oid='public.record_payout_attempt_result(uuid,text,text,jsonb)'::regprocedure)
union all select 'a4', (select 'defn='||md5(pg_get_functiondef(p.oid))||' prosrc='||md5(p.prosrc)||' | args='||pg_get_function_identity_arguments(p.oid)||' | result='||pg_get_function_result(p.oid)||' | secdef='||p.prosecdef::text||' | cfg='||coalesce(array_to_string(p.proconfig,';'),'<none>')||' | acl='||coalesce(p.proacl::text,'<default>')||' owner='||p.proowner::regrole::text from pg_proc p where p.oid='public.flag_payout_reversal_required(uuid,text,jsonb)'::regprocedure)
union all select 'claim148_prosrc', (select md5(prosrc) from pg_proc where oid='public.claim_payout_attempt(uuid,text,interval)'::regprocedure)
union all select 'notify148_prosrc', (select md5(prosrc) from pg_proc where oid='public.notify_transfer_state_inbox()'::regprocedure)
union all select 'census', 'tables='||(select count(*) from pg_tables where schemaname='public')||' functions='||(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public')||' policies='||(select count(*) from pg_policies where schemaname='public')||' triggers='||(select count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal)
union all select 'switches', (select string_agg(key||'='||value::text, ' ' order by key) from ops.setting where key in ('refund_resolution_detector_enabled','alert_delivery_enabled','detectors_enabled'))
union all select 'grants_md5', (select md5(string_agg(grantee||'|'||table_name||'|'||privs, E'\n' order by grantee, table_name)) from (select grantee, table_name, string_agg(privilege_type, ',' order by privilege_type) privs from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated','service_role') group by grantee, table_name) g)
union all select 'info_payout_attempts', (select count(*)::text from public.payout_attempts)
union all select 'info_payout_decisions', (select count(*)::text from public.payout_decisions)
union all select 'info_dispute_resolutions', (select count(*)::text from public.dispute_resolutions)
union all select 'info_seller_win_rows', (select count(*)::text from public.transfers where status='buyer_confirmed' and buyer_confirmed_at is null and dispute_resolution='resolved_seller_paid')
union all select 'info_open_disputes', (select count(*)::text from public.transfers where disputed_at is not null and dispute_resolved_at is null)
union all select 'now', now()::text
